CREATE TYPE "signing_key_event_type" AS ENUM ('REGISTERED', 'ACTIVATED', 'RETIRED', 'REVOKED');
CREATE TABLE "extension_releases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "version" varchar(64) NOT NULL, "release_channel" varchar(32) NOT NULL, "artifact_sha256" varchar(64), "released_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "extension_releases_version_unique" UNIQUE("version"), CONSTRAINT "extension_releases_artifact_sha256_format" CHECK ("artifact_sha256" IS NULL OR "artifact_sha256" ~ '^[0-9a-f]{64}$'));
CREATE TABLE "extension_release_contracts" ("release_id" uuid NOT NULL, "contract_version" varchar(64) NOT NULL, CONSTRAINT "extension_release_contracts_release_id_contract_version_pk" PRIMARY KEY("release_id","contract_version"));
CREATE TABLE "extension_release_browsers" ("release_id" uuid NOT NULL, "browser_family" "browser_family" NOT NULL, CONSTRAINT "extension_release_browsers_release_id_browser_family_pk" PRIMARY KEY("release_id","browser_family"));
CREATE TABLE "compatibility_policy_revisions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "policy_key" varchar(64) NOT NULL, "revision" integer NOT NULL, "contract_version" varchar(64) NOT NULL, "browser_family" "browser_family", "minimum_extension_version" varchar(64), "recommended_extension_version" varchar(64), "minimum_browser_version" varchar(64), "maintenance_mode" boolean DEFAULT false NOT NULL, "maintenance_code" varchar(64), "published_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "compatibility_policy_revisions_policy_key_revision_unique" UNIQUE("policy_key","revision"), CONSTRAINT "compatibility_policy_revisions_revision_positive" CHECK ("revision" > 0));
CREATE TABLE "compatibility_policy_blocked_versions" ("policy_revision_id" uuid NOT NULL, "extension_version" varchar(64) NOT NULL, CONSTRAINT "compatibility_policy_blocked_versions_policy_revision_id_extension_version_pk" PRIMARY KEY("policy_revision_id","extension_version"));
CREATE TABLE "signing_keys" ("key_id" varchar(64) PRIMARY KEY NOT NULL, "algorithm" varchar(16) NOT NULL, "public_key_spki_der" bytea NOT NULL, "public_key_sha256" varchar(64) NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "signing_keys_algorithm_ed25519" CHECK ("algorithm" = 'Ed25519'), CONSTRAINT "signing_keys_public_key_sha256_format" CHECK ("public_key_sha256" ~ '^[0-9a-f]{64}$'), CONSTRAINT "signing_keys_public_key_sha256_unique" UNIQUE("public_key_sha256"));
CREATE TABLE "signing_key_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "key_id" varchar(64) NOT NULL, "event_type" "signing_key_event_type" NOT NULL, "occurred_at" timestamp with time zone NOT NULL, "reason_code" varchar(64), "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX "signing_key_events_key_id_occurred_at_index" ON "signing_key_events" USING btree ("key_id","occurred_at");
CREATE TABLE "config_releases" ("config_version" integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY NOT NULL, "contract_version" varchar(64) NOT NULL, "snapshot_version" varchar(64) NOT NULL, "envelope_version" varchar(64) NOT NULL, "content_hash_sha256" varchar(64) NOT NULL, "source_fingerprint_sha256" varchar(64) NOT NULL, "signing_key_id" varchar(64) NOT NULL, "published_at" timestamp with time zone NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "config_releases_content_hash_sha256_format" CHECK ("content_hash_sha256" ~ '^[0-9a-f]{64}$'), CONSTRAINT "config_releases_source_fingerprint_sha256_format" CHECK ("source_fingerprint_sha256" ~ '^[0-9a-f]{64}$'));
CREATE TABLE "config_release_compatibility_policies" ("config_version" integer NOT NULL, "policy_revision_id" uuid NOT NULL, CONSTRAINT "config_release_compatibility_policies_config_version_policy_revision_id_pk" PRIMARY KEY("config_version","policy_revision_id"));
ALTER TABLE "extension_release_contracts" ADD CONSTRAINT "extension_release_contracts_release_id_fk" FOREIGN KEY ("release_id") REFERENCES "extension_releases"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "extension_release_browsers" ADD CONSTRAINT "extension_release_browsers_release_id_fk" FOREIGN KEY ("release_id") REFERENCES "extension_releases"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "compatibility_policy_blocked_versions" ADD CONSTRAINT "compatibility_policy_blocked_versions_policy_revision_id_fk" FOREIGN KEY ("policy_revision_id") REFERENCES "compatibility_policy_revisions"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "signing_key_events" ADD CONSTRAINT "signing_key_events_key_id_fk" FOREIGN KEY ("key_id") REFERENCES "signing_keys"("key_id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "config_releases" ADD CONSTRAINT "config_releases_signing_key_id_fk" FOREIGN KEY ("signing_key_id") REFERENCES "signing_keys"("key_id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "config_release_compatibility_policies" ADD CONSTRAINT "config_release_compatibility_policies_config_version_fk" FOREIGN KEY ("config_version") REFERENCES "config_releases"("config_version") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "config_release_compatibility_policies" ADD CONSTRAINT "config_release_compatibility_policies_policy_revision_id_fk" FOREIGN KEY ("policy_revision_id") REFERENCES "compatibility_policy_revisions"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE FUNCTION p3_2_reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'P3.2 immutable records cannot be %', TG_OP USING ERRCODE = '55000'; END; $$;
CREATE TRIGGER p3_2_extension_releases_immutable BEFORE UPDATE OR DELETE ON "extension_releases" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_extension_release_contracts_immutable BEFORE UPDATE OR DELETE ON "extension_release_contracts" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_extension_release_browsers_immutable BEFORE UPDATE OR DELETE ON "extension_release_browsers" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_policy_revisions_immutable BEFORE UPDATE OR DELETE ON "compatibility_policy_revisions" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_blocked_versions_immutable BEFORE UPDATE OR DELETE ON "compatibility_policy_blocked_versions" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_signing_keys_immutable BEFORE UPDATE OR DELETE ON "signing_keys" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_signing_key_events_immutable BEFORE UPDATE OR DELETE ON "signing_key_events" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_config_releases_immutable BEFORE UPDATE OR DELETE ON "config_releases" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
CREATE TRIGGER p3_2_config_policy_links_immutable BEFORE UPDATE OR DELETE ON "config_release_compatibility_policies" FOR EACH ROW EXECUTE FUNCTION p3_2_reject_immutable_mutation();
